        /**
         * A local identifier used to track the payment.
         *
         * Will only be `None` for events serialized with LDK Node v0.2.1 or prior.
         */
        val `paymentId`: PaymentId?, 
        /**
         * The hash of the payment.
         */
        val `paymentHash`: PaymentHash, 
        /**
