                + FfiConverterTypeTxid.allocationSize(value.`txid`)
            )
        }
        is UnifiedPaymentResult.Bolt11 -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypePaymentId.allocationSize(value.`paymentId`)
            )
        }
        is UnifiedPaymentResult.Bolt12 -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypePaymentId.allocationSize(value.`paymentId`)
            )
        }
    }

    override fun write(value: UnifiedPaymentResult, buf: ByteBuffer) {
        when(value) {
            is UnifiedPaymentResult.Onchain -> {
                buf.putInt(1)
                FfiConverterTypeTxid.write(value.`txid`, buf)
                Unit
            }
            is UnifiedPaymentResult.Bolt11 -> {
                buf.putInt(2)
                FfiConverterTypePaymentId.write(value.`paymentId`, buf)
                Unit
            }
            is UnifiedPaymentResult.Bolt12 -> {
