/**
 * Supported BIP39 mnemonic word counts for entropy generation.
 */

enum class WordCount {
    
    /**
     * 12-word mnemonic (128-bit entropy)
     */
    WORDS12,
    /**
     * 15-word mnemonic (160-bit entropy)
     */
    WORDS15,
    /**
     * 18-word mnemonic (192-bit entropy)
     */
    WORDS18,
    /**
     * 21-word mnemonic (224-bit entropy)
     */
    WORDS21,
    /**
     * 24-word mnemonic (256-bit entropy)
     */
    WORDS24;
    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypeWordCount: FfiConverterRustBuffer<WordCount> {
    override fun read(buf: ByteBuffer) = try {
        WordCount.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: WordCount) = 4UL

    override fun write(value: WordCount, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}






